// Bilingual site: Chinese by default, English on request.
// Content blocks carry .lang-zh / .lang-en (CSS hides the inactive one);
// template-owned strings (nav, page titles) are swapped from the table below.
(function () {
  var KEY = "site-lang";
  var ZH = {
    about: "主页",
    blog: "博客",
    publications: "论文",
    projects: "项目",
    news: "新闻",
    CV: "简历",
    repositories: "代码仓库",
    "ctrl k": "搜索",
    "publications by categories in reversed chronological order. generated by jekyll-scholar.": "按时间倒序排列。",
    "Research projects and open-source releases.": "研究项目与开源发布。",
    "an archive of posts in this category": "",
  };

  function get() {
    // ?lang=en / ?lang=zh in the URL wins (handy for sharing a link in one language)
    var q = new URLSearchParams(location.search).get("lang");
    if (q === "en" || q === "zh") {
      try {
        localStorage.setItem(KEY, q);
      } catch (e) {}
      return q;
    }
    try {
      return localStorage.getItem(KEY) || "zh";
    } catch (e) {
      return "zh";
    }
  }

  function swapText(lang) {
    var nodes = document.querySelectorAll(".navbar-nav .nav-link, .post-title, .post-description, #search-toggle .nav-link");
    nodes.forEach(function (el) {
      // only swap the leading text node, keep icons / children intact
      var t = null;
      for (var i = 0; i < el.childNodes.length; i++) {
        var n = el.childNodes[i];
        if (n.nodeType === 3 && n.textContent.trim()) {
          t = n;
          break;
        }
      }
      if (!t) return;
      if (t.__en === undefined) t.__en = t.textContent;
      var key = t.__en.trim();
      t.textContent = lang === "zh" && ZH[key] !== undefined ? t.__en.replace(key, ZH[key]) : t.__en;
    });
    var bs = document.querySelector("#bibsearch, input.search");
    if (bs) bs.placeholder = lang === "zh" ? "输入关键词筛选" : "Type to filter";
  }

  function apply(lang) {
    document.documentElement.setAttribute("data-lang", lang);
    document.documentElement.setAttribute("lang", lang === "zh" ? "zh-CN" : "en");
    swapText(lang);
    var btn = document.getElementById("lang-toggle");
    if (btn) btn.textContent = lang === "zh" ? "EN" : "中";
    if (btn) btn.title = lang === "zh" ? "Switch to English" : "切换到中文";
  }

  function addButton() {
    var list = document.querySelector(".navbar-nav");
    if (!list || document.getElementById("lang-toggle")) return;
    var li = document.createElement("li");
    li.className = "nav-item lang-toggle-item";
    var btn = document.createElement("button");
    btn.id = "lang-toggle";
    btn.type = "button";
    btn.className = "lang-toggle";
    btn.addEventListener("click", function () {
      var next = get() === "zh" ? "en" : "zh";
      try {
        localStorage.setItem(KEY, next);
      } catch (e) {}
      apply(next);
    });
    li.appendChild(btn);
    var themeToggle = list.querySelector(".toggle-container");
    list.insertBefore(li, themeToggle || null);
  }

  function init() {
    addButton();
    apply(get());
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
  else init();
})();
